import React, { useEffect, useRef, useState } from "react";
import TimelineScroller from "./components/TimelineScroller";
import VideoPlayer from "./components/VideoPlayer";

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function App() {
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);

  const [videoSrc, setVideoSrc] = useState("");
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  const openFilePicker = () => fileInputRef.current?.click();

  // 🔥 UPLOAD TO BACKEND (CRITICAL FIX)
  const handleFileChange = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setUploadError("");

    try {
      const formData = new FormData();
      formData.append("video", file);

      const response = await fetch("http://localhost:5000/upload", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Upload failed");
      }

      // 🔥 USE CONVERTED VIDEO FROM BACKEND
      const previewUrl = `http://localhost:5000${data.preview_video}`;

      setVideoSrc(previewUrl);
      setCurrentTime(0);
      setDuration(0);

    } catch (err) {
      setUploadError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (!video) return;

    if (video.paused) video.play();
    else video.pause();
  };

  const handleSeek = (time) => {
    const video = videoRef.current;
    if (!video || duration <= 0) return;

    const t = clamp(time, 0, duration);
    video.currentTime = t;
    setCurrentTime(t);
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white py-10">
      <div className="mx-auto max-w-[1200px] px-4">
        <div className="mb-6 rounded-[28px] border border-white/10 bg-slate-950/95 p-6 shadow-[0_24px_80px_rgba(0,0,0,0.2)]">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="min-w-0">
              <h1 className="text-2xl font-semibold text-white">Video Tampering Detection</h1>
              <p className="mt-2 text-sm text-slate-400">
                Upload a video to detect tampered segments and review results in a clean dashboard layout.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <button
                type="button"
                onClick={openFilePicker}
                className="rounded-full border border-slate-700 bg-slate-900 px-4 py-2 text-sm font-semibold text-white transition hover:border-slate-500"
              >
                Upload video
              </button>
            </div>
          </div>
        </div>

        <div className="grid gap-6 lg:grid-cols-[3fr_1fr] items-stretch h-[520px]">
          <div className="flex flex-col overflow-hidden rounded-[28px] border border-white/10 bg-slate-950/95 shadow-[0_24px_80px_rgba(0,0,0,0.2)]">
            <div className="flex-1 min-h-0 p-5">
              <VideoPlayer
                ref={videoRef}
                src={videoSrc}
                isPlaying={isPlaying}
                currentTime={currentTime}
                onTogglePlay={handleTogglePlay}
                onTimeUpdate={setCurrentTime}
                onDurationChange={setDuration}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                hasVideo={!!videoSrc}
              />
            </div>
            <div className="min-h-0 border-t border-white/10 px-5 py-4">
              <TimelineScroller
                duration={duration}
                currentTime={currentTime}
                loading={loading}
                onSeek={handleSeek}
                onUploadClick={openFilePicker}
              />
            </div>
          </div>

          <div className="flex flex-col overflow-hidden rounded-[28px] border border-white/10 bg-slate-950/95 p-5 shadow-[0_24px_80px_rgba(0,0,0,0.2)]">
            <div className="flex-1 flex flex-col justify-between gap-6">
              <div>
                <div className="text-sm font-semibold uppercase tracking-[0.24em] text-rose-400">Analysis</div>
                <h2 className="mt-4 text-2xl font-semibold text-white">Results panel</h2>
                <p className="mt-3 text-sm text-slate-400">
                  Upload a clip to see tampering detection details, duration stats, and action controls.
                </p>
              </div>

              <div className="grid gap-4">
                <div className="rounded-[20px] bg-slate-900/90 p-4">
                  <div className="text-sm text-slate-400">Video duration</div>
                  <div className="mt-2 text-lg font-semibold text-white">
                    {duration ? `${Math.floor(duration / 60).toString().padStart(2, "0")}:${Math.floor(duration % 60).toString().padStart(2, "0")}` : "00:00"}
                  </div>
                </div>
                <div className="rounded-[20px] bg-slate-900/90 p-4">
                  <div className="text-sm text-slate-400">Status</div>
                  <div className="mt-2 text-lg font-semibold text-white">{videoSrc ? "Ready to analyze" : "Waiting for upload"}</div>
                </div>
              </div>

              <div className="space-y-3">
                <button
                  type="button"
                  className="w-full rounded-full bg-slate-900 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800"
                  disabled={!videoSrc}
                >
                  View results
                </button>
                <button
                  type="button"
                  className="w-full rounded-full bg-white/10 px-4 py-3 text-sm font-semibold text-white transition hover:bg-white/20"
                  disabled={!videoSrc}
                >
                  Download report
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <input
        type="file"
        accept="video/*"
        ref={fileInputRef}
        className="hidden"
        onChange={handleFileChange}
      />

      {uploadError && (
        <div className="mx-auto mt-4 max-w-[1200px] rounded-[20px] border border-red-500/20 bg-red-500/10 px-4 py-3 text-sm text-red-200">
          {uploadError}
        </div>
      )}
    </div>
  );
}
